// Inherit the pinned endpoint table and exact arithmetic from R247.
const pencils=new Map();
for (const [t,b,d] of P) {
  const r=gcd(t,b);
  if (!r) continue;
  const T=t/r, U=b/r;
  const key=T+","+U;
  if (!pencils.has(key)) pencils.set(key,{T,U,ordinates:[]});
  pencils.get(key).ordinates.push([d,r]);
}
const lines=[];
const groupSizes=[];
for (const {T,U,ordinates} of pencils.values()) {
  const group=new Map();
  for (let i=0;i<ordinates.length;i++) for (let j=i+1;j<ordinates.length;j++) {
    const [a,b]=ordinates[i], [d,e]=ordinates[j];
    if (a*e===b*d) throw Error("same ordinate on a pencil");
    const line=norm([T*b*e,U*b*e,a*e+b*d]);
    group.set(line.join(),line);
  }
  groupSizes.push([String(T),String(U),ordinates.length,group.size]);
  lines.push(...group.values());
}
const vertices=new Map();
let nonparallelPairs=0;
for (let i=0;i<lines.length;i++) for (let j=i+1;j<lines.length;j++) {
  const point=cross(lines[i],lines[j]);
  if (!point[2]) continue;
  nonparallelPairs++;
  const key=norm(point, true).join();
  if (!vertices.has(key)) vertices.set(key,new Set());
  vertices.get(key).add(i);
  vertices.get(key).add(j);
}
let chambers=1+lines.length, edges=lines.length;
const vertexMultiplicities={};
for (const incidences of vertices.values()) {
  const m=incidences.size;
  chambers+=m-1;
  edges+=m;
  vertexMultiplicities[m]=(vertexMultiplicities[m]??0)+1;
}
const dimensions=[vertices.size,edges,chambers];
if (dimensions[0]-dimensions[1]+dimensions[2]!==1) throw Error("Euler count");
return {groupSizes,lines:lines.length,nonparallelPairs,vertexMultiplicities,dimensions,
        total:dimensions.reduce((x,y)=>x+y,0)};

