const dotWide = (a,b) => a.reduce((sum,x,i) => sum+x*b[i],0n);
const monos = [[0,0],[1,1],[2,2],[0,1],[0,2],[1,2]];
const pointRow = p => monos.map(([i,j])=>p[i]*p[j]);
const jetRows = G.map(([u,v]) => {
  const p=P[u], q=sub(P[v],p);
  return [pointRow(p),monos.map(([i,j])=>p[i]*q[j]+p[j]*q[i]),pointRow(q)];
});
const grouped=new Map();
for(const {a,b,zeros} of upstream.final) {
  const key=zeros.join();
  if(!grouped.has(key)) grouped.set(key,{zeros,targets:new Set()});
  grouped.get(key).targets.add(a+","+b);
}
const results=[];
for(const {zeros,targets} of grouped.values()) {
  let basis=Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>i===j?1n:0n));
  for (const z of zeros) {
    const row=pointRow(P[z]);
    const values=basis.map(x=>dotWide(x,row));
    const p=values.findIndex(Boolean);
    if(p<0) throw Error("dependent zero constraint");
    basis=basis.flatMap((x,i)=>i===p?[]:[
      norm(x.map((y,j)=>values[p]*y-values[i]*basis[p][j]))
    ]);
  }
  if (basis.length!==2) throw Error("not a projective line");
  if(!basis[0][2]) basis.reverse();
  if(!basis[0][2]) throw Error("no positive c chart");
  const origin=scale(basis[0],BigInt(sg(basis[0][2])));
  const direction=norm(basis[1].map((y,j)=>origin[2]*y-basis[1][2]*origin[j]));
  if(direction[2] || !direction.some(Boolean)) throw Error("invalid c=constant chart");
  const rows=jetRows.map(rows=>rows.map(row=>[dotWide(row,origin),dotWide(row,direction)]));
  const slopeForms=[4,5].map(j=>[origin[j],direction[j]]);
  const events=new Map();
  for(const [a,b] of [...rows.flat(),...slopeForms]) if(b) {
    const r=norm([-a,b]);
    if(r[1]<0n) for(let j=0;j<2;j++) r[j]=-r[j];
    events.set(r.join(),r);
  }
  const cuts=[...events.values()].sort(([a,b],[c,d])=>sg(a*d-b*c));
  if(!cuts.length) cuts.push([0n,1n]);
  const reps=[[cuts[0][0]-cuts[0][1],cuts[0][1]]];
  for(let i=0;i<cuts.length;i++) {
    reps.push(cuts[i]);
    const [a,b]=cuts[i];
    if(i+1<cuts.length) {
      const [c,d]=cuts[i+1];
      reps.push([a*d+b*c,2n*b*d]);
    } else reps.push([a+b,b]);
  }
  const matches=[];
  let inside=0, complete=0;
  const masks=new Set();
  for(const [n,d] of reps) {
    const evalRow=([a,b])=>a*d+b*n;
    if(slopeForms.some(row=>evalRow(row)<0n)) continue;
    inside++;
    let a=0n,b=0n;
    for(let i=0;i<rows.length;i++) {
      const value=rows[i].map(evalRow).find(Boolean)??0n;
      if(value>0n) a|=G[i][2];
      else if(value<0n) b|=G[i][2];
    }
    if((a|b)!==ALL) continue;
    complete++;
    const key=a.toString(16)+","+b.toString(16);
    masks.add(key);
    if(targets.has(key)) matches.push([n,d].map(String));
  }
  results.push({zeros, anchors:zeros.map(i=>P[i].map(String)),
    origin:origin.map(String),direction:direction.map(String),
    targetMasks:targets.size,events:events.size,inside,complete,distinctMasks:masks.size,matches});
}
return {results};

